     9→<body class="home">
    10→  <main class="home-main">
    11→    <h1>Fog of War</h1>
    12→
    13→    <section class="card">
    14→      <h2>Create Adventure</h2>
    15→      <form id="create-form">
    16→        <label>Adventure name<input type="text" id="adv-name" required placeholder="The Lost Mines"></label>
    17→        <label>GM password<input type="password" id="adv-password" required placeholder="secret"></label>
    18→        <button type="submit">Create</button>
    19→        <p id="create-error" class="error"></p>
    20→      </form>
    21→    </section>
    22→
    23→    <section class="card">
    24→      <h2>Join Adventure</h2>
    25→      <form id="join-form">
    26→        <label>Invite code<input type="text" id="join-link" required placeholder="abc123"></label>
    27→        <label>Your name<input type="text" id="join-name" required placeholder="Aria"></label>
    28→        <label>Color<input type="color" id="join-color" value="#e74c3c"></label>
    29→        <button type="submit">Join</button>
    30→        <p id="join-error" class="error"></p>
    31→      </form>
    32→    </section>
    33→  </main>
    34→
    35→  <script>
    36→    document.getElementById('create-form').addEventListener('submit', async (e) => {
    37→      e.preventDefault();
    38→      const name = document.getElementById('adv-name').value.trim();
    39→      const password = document.getElementById('adv-password').value;
    40→      const errEl = document.getElementById('create-error');
    41→      errEl.textContent = '';
    42→      try {
    43→        const res = await fetch('/api/adventures', {
    44→          method: 'POST',
    45→          headers: { 'Content-Type': 'application/json' },
    46→          body: JSON.stringify({ name, gmPassword: password }),
    47→        });
    48→        if (!res.ok) {
    49→          const data = await res.json();
    50→          errEl.textContent = data.error || 'Error creating adventure';
    51→          return;
    52→        }
    53→        const adv = await res.json();
    54→        location.href = `/gm#id=${encodeURIComponent(adv.id)}&password=${encodeURIComponent(password)}`;
    55→      } catch (err) {
    56→        errEl.textContent = String(err);
    57→      }
    58→    });
    59→
    60→    document.getElementById('join-form').addEventListener('submit', async (e) => {
    61→      e.preventDefault();
    62→      const link = document.getElementById('join-link').value.trim();
    63→      const name = document.getElementById('join-name').value.trim();
    64→      const color = document.getElementById('join-color').value;
    65→      const errEl = document.getElementById('join-error');
    66→      errEl.textContent = '';
    67→      try {
    68→        const res = await fetch(`/api/adventures/join/${encodeURIComponent(link)}`);
    69→        if (!res.ok) {
    70→          errEl.textContent = 'Invalid invite code.';
    71→          return;
    72→        }
    73→        const adv = await res.json();
    74→        location.href = `/player#adventureId=${encodeURIComponent(adv.id)}&link=${encodeURIComponent(link)}&name=${encodeURIComponent(name)}&color=${encodeURIComponent(color)}`;
    75→      } catch {
    76→        errEl.textContent = 'Could not connect to server.';
    77→      }
    78→    });
    79→  </script>
    80→</body>
    81→</html>
