*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: system-ui, sans-serif;
  background: #0d0d1a;
  color: #e0e0e0;
  height: 100vh;
  overflow: hidden;
}

/* ── Home page ── */
body.home {
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: auto;
}
.home-main { width: 100%; max-width: 480px; padding: 2rem; }
.home-main h1 { font-size: 2rem; margin-bottom: 1.5rem; text-align: center; }
.card {
  background: #1a1a2e;
  border: 1px solid #2a2a4a;
  border-radius: 8px;
  padding: 1.5rem;
  margin-bottom: 1rem;
}
.card h2 { margin-bottom: 1rem; font-size: 1.1rem; }
.card label { display: flex; flex-direction: column; gap: 4px; margin-bottom: 0.75rem; font-size: 0.85rem; color: #aaa; }
.card input[type=text],
.card input[type=password],
.card input[type=color] {
  padding: 0.4rem 0.6rem;
  background: #0d0d1a;
  border: 1px solid #333;
  border-radius: 4px;
  color: #e0e0e0;
  font-size: 1rem;
}
.card input[type=color] { height: 2rem; cursor: pointer; }
.card button {
  width: 100%;
  padding: 0.5rem;
  background: #4a4aff;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 1rem;
}
.card button:hover { background: #3333cc; }
.error { color: #e74c3c; margin-top: 0.5rem; font-size: 0.85rem; }

/* ── Canvas area (GM and Player) ── */
#canvas-area {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #080810;
  overflow: hidden;
  touch-action: none;
}

/* ── Floating control base ── */
.floating-control {
  position: fixed;
  z-index: 10;
  background: rgba(26, 26, 46, 0.6);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(42, 42, 74, 0.5);
  border-radius: 8px;
  color: #e0e0e0;
  pointer-events: auto;
  transition: opacity 200ms ease-out, transform 200ms ease-out;
}

/* ── Floating panel (slide-out sheets) ── */
.floating-panel {
  position: fixed;
  z-index: 10;
  background: rgba(26, 26, 46, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(42, 42, 74, 0.5);
  border-left: 1px solid rgba(42, 42, 74, 0.5);
  color: #e0e0e0;
  pointer-events: auto;
  transition: transform 200ms ease-out, opacity 200ms ease-out;
}

/* ── GM Topbar ── */
#topbar {
  top: 8px;
  left: 8px;
  right: 8px;
  height: 44px;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0 0.75rem;
}
#adventure-name {
  font-weight: 600;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Connection status dot ── */
.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #555;
  flex-shrink: 0;
}
.status-dot.connected { background: #22c55e; }
.status-dot.disconnected { background: #e74c3c; }

/* ── Player presence avatar stack ── */
#player-presence {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}
.presence-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: #fff;
  cursor: pointer;
  border: 2px solid transparent;
