  font-size: 0.85rem;
  transition: background 150ms ease-out, color 150ms ease-out;
  touch-action: auto;
}
#mode-toggle button.active { background: #4a4aff; color: #fff; }
#mode-toggle button:not(.active):hover { background: rgba(255, 255, 255, 0.05); color: #ccc; }

/* ── Map panel toggle: right edge icon button ── */
#map-panel-toggle {
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
  background: rgba(26, 26, 46, 0.6);
}
#map-panel-toggle:hover { background: rgba(42, 42, 74, 0.8); }
#map-panel-toggle.active { background: rgba(74, 74, 255, 0.25); border-color: #4a4aff; }

/* ── Map panel: right-side slide-in sheet ── */
#map-panel {
  right: 0;
  top: 60px;
  bottom: 0;
  width: 200px;
  display: flex !important;
  flex-direction: column;
  border-radius: 8px 0 0 8px;
  transform: translateX(0);
  opacity: 1;
}
#map-panel[hidden] {
  transform: translateX(105%);
  opacity: 0;
  pointer-events: none;
}
#gallery {
  flex: 1;
  overflow-y: auto;
  padding: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.gallery-item {
  border: 2px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  overflow: hidden;
  background: #0d0d1a;
  touch-action: auto;
}
.gallery-item:hover { border-color: #4a4aff88; }
.gallery-item.active { border-color: #4a4aff; }
.gallery-item img { width: 100%; height: 80px; object-fit: cover; display: block; }
.upload-btn {
  display: block;
  text-align: center;
  padding: 0.4rem;
  margin: 0.5rem;
  background: rgba(26, 26, 46, 0.5);
  border: 1px dashed #444;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.85rem;
  color: #aaa;
  touch-action: auto;
}
.upload-btn:hover { border-color: #4a4aff; color: #ccc; }

/* ── Status bar ── */
#status-bar {
  bottom: 68px;
  left: 8px;
  padding: 0.25rem 0.5rem;
  font-size: 0.75rem;
  color: #aaa;
  pointer-events: none;
  min-width: 0;
}
#status-bar:empty { display: none; }

/* ── Player badge: top-left corner pill ── */
#player-badge {
  top: 8px;
  left: 8px;
  display: flex;
  align-items: center;
  padding: 0.3rem 0.75rem;
  height: 36px;
  border-radius: 18px;
}
#player-info {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.9rem;
}
.player-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.3);
  flex-shrink: 0;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 1rem;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(26, 26, 46, 0.95);
  border: 1px solid #2a2a4a;
  border-radius: 4px;
  padding: 0.4rem 0.8rem;
  font-size: 0.85rem;
  color: #ccc;
  pointer-events: none;
  z-index: 100;
}

/* ── Removal overlay ── */
.removal-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  background: rgba(13, 13, 26, 0.92);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 200;
}
.removal-overlay p {
  font-size: 1.1rem;
  color: #ccc;
}
.removal-overlay a {
  color: #4a4aff;
  text-decoration: none;
}
.removal-overlay a:hover { text-decoration: underline; }

